/***********************************************************************
 * - 2018.03.28 수정                                                                                             *
 * if (getObjectValue(txb_form_cd) != "") {fn_GetVersion();}                                *
 * 주석 처리 - 검색 조건 변경 시 fn_GetVersion() 호출 X  (조회 클릭 시 호출)  *
 ************************************************************************/

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    rdo_mkt_id.setValue(js_market);
    if (js_market === "3") {
        rdo_mkt_id.setValue("9");
    } // 20140318  파생상품은 전체 조회되게 기능 추가

    cmb_dep_cd.setValue(js_dep_cd);
    cmb_emp_no.setValue(js_emp_no);
    cmb_periodTp.setValue("3");
};

/**
 * @method
 * @name compareVersion
 * @description Grid 버전 체크해서 엑셀저장시 gridtoExcel or gridtoOffice 구분
 * @param {*} grid grid
 * @returns {void}
 * @hidden N
 */
scwin.compareVersion = function(grid) {
    let result = false;
    const verA = grid.Version.split(',');
    const verB = "2,0,1,326".split(','); // 기준버전 입력

    const length = (verA.length > verB.length) ? verA.length : verB.length;
    for (let i = 0; i < length; i++) {
        const a = verA[i] ? parseInt(verA[i], 10) : 0;
        const b = verB[i] ? parseInt(verB[i], 10) : 0;
        if (a > b) {
            result = true;
            break;
        }
        if (i === length - 1 && a === b) {
            result = true;
            break;
        }
    }
    return result;
};

/**
 * @method
 * @name sleep
 * @description process wait state 함수 - numberMillis 수치만큼 wait.
 * @param {*} numberMillis numberMillis
 * @returns {void}
 * @hidden N
 */
scwin.sleep = function(numberMillis) {
    let now = new Date();
    const exitTime = now.getTime() + numberMillis;
    while (true) {
        now = new Date();
        if (now.getTime() > exitTime) return;
    }

};

// 화면 UI 로그 삭제 함수 (개발시에만 로그조회를 위해  txaMain textarea 컴포넌트를 추가하여 사용.)

