 * @description 상단그리드에 체크된 항목 구하기
 * @returns {void}
 * @hidden N
 */
scwin.getSelectedItems = function() {
    let selectedItems = "";
    for (let j = 1; j < dts_item_dummy.CountColumn + 1; j++) {

        const itemValue = dts_item_dummy.ColumnID(j);

        if ("T" === dts_item_dummy.NameString(1, itemValue)) {
            selectedItems += itemValue + "|";
        }
    }
    scwin.SetLog("선택항목", selectedItems);
    return selectedItems;
};

