        $c.stf.doLogSave('ULDSTF25007.gfm', SCREN_PROCS_TP_CD_07);
        let file_name = txb_form_kor_nm.getValue();
        const today = $c.ut.cGetToday('yyyymmddhhmmss');
        file_name = file_name.replace(/\//g, "");
        const xls_path = $c.session.getExcelDownPath() + today + "_" + file_name + ".xlsx";

        file_name = file_name.substring(0, 30); // 오류 : GridToExcel-SheetName 길이가 31 이상이 될 수 없습니다.

        if (scwin.compareVersion(grd_main)) {

